-- Fail closed if a rerun would silently introduce a competing method or dates.
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM public.km_venus_visibility_windows w JOIN venus_visibility_import i
 ON tstzrange(w.start_ts,w.end_ts,'[]') && tstzrange(i.start_ts,i.end_ts,'[]')
 WHERE (w.start_ts,w.end_ts,w.start_event,w.end_event) IS DISTINCT FROM
       (i.start_ts,i.end_ts,i.start_event,i.end_event)
 OR w.parameters IS DISTINCT FROM '{"location": "Ujjain", "geopos": [75.7885, 23.1793, 494.0], "atmosphere": [1013.25, 25.0, 40.0, 0.24], "observer": [36.0, 3.25, 0, 0, 0, 0], "ephemeris": "Moshier", "timezone": "Asia/Kolkata", "engine": "2.10.03", "method_version": "venus_visibility_ujjain_v1", "flags": 260, "precision": "calculated_visibility_model", "manual_overrides": false}'
 ::jsonb) THEN RAISE EXCEPTION 'Visibility method/date conflict: explicit migration required'; END IF;
END $$;
