CREATE OR REPLACE VIEW public.km_venus_visibility_calendar AS
 SELECT e.event_type||':'||to_char(w.start_ts AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS')||'Z' AS event_key,e.event_type,d.display_name,d.shape,
 (e.start_ts AT TIME ZONE 'Asia/Kolkata')::date AS start_date,
 (e.end_ts AT TIME ZONE 'Asia/Kolkata')::date AS end_date,e.start_ts,e.end_ts,
 'calculated_visibility_model'::text AS precision,
 'swiss_ephemeris'::text AS source,w.parameters->>'method_version' AS calculation_method,
 w.start_event,w.end_event,w.parameters
 FROM public.km_venus_visibility_windows w CROSS JOIN LATERAL (VALUES
 ('venus_tara_asta',w.start_ts,w.start_ts),
 ('venus_tara_udaya',w.end_ts,w.end_ts),
 ('venus_tara_asta_period',w.start_ts,w.end_ts)
 ) e(event_type,start_ts,end_ts)
 JOIN public.km_astro_event_definition d USING(event_type);
-- Stable unified reader; migration 235's daily-source refresh remains unchanged.
CREATE OR REPLACE VIEW public.km_venus_calendar AS
 SELECT event_key,event_type,display_name,shape,start_date,end_date,start_ts,end_ts,precision,source,calculation_method
 FROM public.km_venus_event_calendar
 UNION ALL
 SELECT event_key,event_type,display_name,shape,start_date,end_date,start_ts,end_ts,precision,source,calculation_method
 FROM public.km_venus_visibility_calendar;
REVOKE ALL ON public.km_venus_visibility_windows FROM PUBLIC;
DO $$ DECLARE role_name text; BEGIN
 FOREACH role_name IN ARRAY ARRAY['anon','authenticated','kd_readonly','kd_app','kd_admin'] LOOP
  IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname=role_name) THEN
   EXECUTE format('REVOKE ALL ON public.km_venus_visibility_windows FROM %I',role_name);
   EXECUTE format('GRANT SELECT ON public.km_venus_visibility_windows,public.km_venus_visibility_calendar,public.km_venus_calendar TO %I',role_name);
  END IF;
 END LOOP;
END $$;
